import { Component } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent {
constructor(private router: Router){}

  ngOnInit(): void {
    const newSessionId = crypto.randomUUID(); // koristi Web Crypto API
    //localStorage.removeItem('sessionId')
    localStorage.setItem('sessionId', newSessionId);
    console.log('Nova test sesija:', newSessionId);
  }


  routeFlanker(){
    localStorage.setItem("test",JSON.stringify("flanker"))
    this.router.navigate(['consent']);
  }

  routeVisual(){
    localStorage.setItem("test",JSON.stringify("visual"))
    this.router.navigate(['/consent']);
  }
}
<div class="container vh-100 d-flex justify-content-center align-items-center">
  <div class="text-center">
    <h1 class="mb-4">Dobrodošli!</h1>
    <p class="lead mb-5">Izaberite koji test želite da radite:</p>

    <div class="d-flex justify-content-center gap-4">
      <button class="btn btn-outline-primary btn-lg px-5"
              (click)="routeFlanker()">
        Flanker test
      </button>

      <button class="btn btn-outline-success btn-lg px-5"
              (click)="routeVisual()">
        Test vizuelne pretrage
      </button>
    </div>
  </div>
</div>
